import{_ as a,o as n,c as i,a3 as t}from"./chunks/framework.MGD2uYU7.js";const f=JSON.parse('{"title":"SC-29 — Hồ sơ cá nhân","description":"","frontmatter":{"title":"SC-29 — Hồ sơ cá nhân"},"headers":[],"relativePath":"wireframes/user/sc-29-ho-so.md","filePath":"wireframes/user/sc-29-ho-so.md","lastUpdated":null}'),l={name:"wireframes/user/sc-29-ho-so.md"};function c(p,s,e,d,o,r){return n(),i("div",null,[...s[0]||(s[0]=[t('<h1 id="sc-29-—-ho-so-ca-nhan" tabindex="-1">SC-29 — Hồ sơ cá nhân <a class="header-anchor" href="#sc-29-—-ho-so-ca-nhan" aria-label="Permalink to &quot;SC-29 — Hồ sơ cá nhân&quot;">​</a></h1><p><span class="wf-badge muted">ƯU TIÊN THẤP (MS1)</span> <span class="wf-badge info">Route: /ho-so</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-29 · docs/02 FR-IDT-04/05/07 · docs/08 BR-IDT-01/02 · BR-ADM-04</span></p><p><strong>Ai xem màn này</strong>: Thành viên đã đăng nhập (guard USER 🔒) — tự sửa hồ sơ của chính mình. ADMIN <strong>không</strong> sửa hộ user qua màn này (docs/08 §9: &quot;Sửa hồ sơ mình — ADMIN ⛔, xử qua ops&quot;). <strong>Mục đích</strong>: sửa thông tin liên hệ hiển thị (tên / SĐT / avatar) và đổi mật khẩu. Hai nguyên tắc bất biến: <strong>email READ-ONLY</strong> (định danh đăng nhập duy nhất) và <strong>mật khẩu mới phải qua rule BR-IDT-02</strong>. <strong>Ví dụ số dùng trong bản vẽ</strong>: NGUYEN VAN A · email <code>nguyenvana@example.com</code> · SĐT <code>0912 345 678</code> · KYC APPROVED 08/10/2026 · gói VIP_STANDARD đến 07/11/2026 · &quot;bây giờ&quot; 10/10/2026 14:35 (GMT+7).</p><h2 id="_1-desktop-—-form-ho-so-cot-trang-thai-tai-khoan" tabindex="-1">1. Desktop — form hồ sơ + cột trạng thái tài khoản <a class="header-anchor" href="#_1-desktop-—-form-ho-so-cot-trang-thai-tai-khoan" aria-label="Permalink to &quot;1. Desktop — form hồ sơ + cột trạng thái tài khoản&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/ho-so</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">3</span></span><span class="wf-avatar" style="border-color:var(--wf-accent);">TV</span></span></div><div class="wf-container"><span class="wf-title xl">Hồ sơ cá nhân</span><div class="wf-row" style="align-items:stretch;margin-top:12px;"><div class="wf-grow wf-col" style="gap:12px;"><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><span class="wf-title">Thông tin cá nhân <span class="wf-callout">1</span></span><div class="wf-row middle" style="gap:12px;"><div class="wf-img" style="min-height:72px;width:72px;flex:none;border-radius:50%;"><span>AVATAR</span></div><div class="wf-col" style="gap:6px;"><span class="wf-btn sm">Đổi ảnh đại diện <span class="wf-callout">3</span></span><span class="wf-small">Hoặc dán URL ảnh: </span><div class="wf-input filled" style="min-width:280px;"><span>https://cdn.anphuc.vn/ava/tv7f2a.png</span><span class="caret">✎</span></div></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Họ tên *</span><div class="wf-input filled"><span>NGUYEN VAN A</span><span class="caret">✎</span></div><span class="wf-small">2–100 ký tự. Sau khi KYC APPROVED, họ tên phải trùng khớp CCCD (chuẩn không dấu/NFC) — nếu đổi tên trên giấy tờ, liên hệ CSKH 1900-xxx TRƯỚC khi sửa ở đây. <span class="wf-callout">2</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Email đăng nhập — <span class="wf-danger-text">KHÔNG THỂ TỰ ĐỔI</span></span><div class="wf-input filled" style="background:var(--wf-fill);color:var(--wf-ink-soft);"><span>🔒 nguyenvana@example.com</span></div><span class="wf-small">Email là định danh đăng nhập duy nhất (unique toàn hệ thống). Cần đổi email: gọi CSKH 1900-xxx — CS xác minh CCCD rồi ADMIN xử lý thủ công (kèm audit). <span class="wf-callout">2</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Số điện thoại</span><div class="wf-input filled"><span>0912 345 678</span><span class="caret">✎</span></div><span class="wf-small">Tối đa 15 ký tự — dùng cho CSKH liên hệ; không bắt buộc, không unique ở v1.</span></div><div class="wf-row" style="margin-top:4px;"><span class="wf-btn primary">Lưu thay đổi <span class="wf-callout">4</span></span><span class="wf-btn ghost">Hủy bỏ thay đổi</span></div></div></div><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><span class="wf-title">Đổi mật khẩu <span class="wf-callout">5</span></span><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Mật khẩu hiện tại *</span><div class="wf-input filled"><span>••••••••••</span><span class="caret">👁</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Mật khẩu mới *</span><div class="wf-input filled"><span>••••••••••••</span><span class="caret">👁</span></div><div class="wf-row" style="gap:4px;margin-top:4px;"><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-ok);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span></div><span class="wf-small wf-ok-text">Mạnh — đạt toàn bộ yêu cầu tối thiểu bên dưới</span><span class="wf-small">Yêu cầu (rule cứng): ≥8 ký tự · ≥1 chữ HOA · ≥1 chữ số · ≥1 ký tự đặc biệt. <span class="wf-callout">6</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Nhập lại mật khẩu mới *</span><div class="wf-input filled"><span>••••••••••••</span><span class="caret">👁</span></div></div><span class="wf-btn primary">Đổi mật khẩu</span><span class="wf-small">Thành công → <b>toàn bộ phiên đăng nhập trên thiết bị khác bị thu hồi</b> (phải đăng nhập lại); phiên hiện tại giữ nguyên. <span class="wf-callout">5</span></span></div></div></div><div class="wf-sidebar wf-sticky-note wf-col" style="gap:10px;"><span class="wf-title">Trạng thái tài khoản <span class="wf-callout">8</span></span><div class="wf-row between"><span class="wf-text">KYC (CCCD)</span><span class="wf-badge ok">APPROVED</span></div><div class="wf-row between"><span class="wf-text">Duyệt lúc</span><span class="wf-small">08/10/2026 10:20</span></div><div class="wf-row between"><span class="wf-text">Gói dịch vụ</span><span class="wf-badge wf-vip">VIP_STANDARD</span></div><div class="wf-row between"><span class="wf-text">Gói hết hạn</span><span class="wf-small">07/11/2026 10:22</span></div><div class="wf-row between"><span class="wf-text">Quyền đấu giá</span><span class="wf-badge ok">GRANTED</span></div><div class="wf-row between"><span class="wf-text">Thành viên từ</span><span class="wf-small">01/10/2026 09:12</span></div><div class="wf-note" style="margin:0;">Các trường trạng thái (KYC / gói / quyền / role) <b>chỉ đọc</b> — thay đổi qua flow nghiệp vụ riêng (SC-21, SC-26), không sửa được từ form hồ sơ.</div><span class="wf-btn sm block ghost">Xem hồ sơ KYC → SC-21</span><span class="wf-btn sm block ghost">Gói của tôi → SC-26</span><span class="wf-small">CSKH 1900-xxx · GMT+7</span></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/02 FR-IDT · docs/08 BR-IDT · docs/06 §5)</div><ol><li><span class="num">1</span><span>Form nạp từ `GET /auth/me` (endpoint 5); lưu bằng `PATCH /users/me` (6) <b>partial</b> — FE chỉ gửi field user thực sự đổi. Validate onBlur + onSubmit, message tại field. <span class="ref">FR-IDT-04</span> <span class="ref">docs/05 §1.5</span></span></li><li><span class="num">2</span><span><b>Email READ-ONLY ở CẢ HAI tầng</b>: UI khóa input + server từ chối (PATCH chỉ chấp nhận fullName/phone/avatarUrl; field thừa → 400 do global whitelist). Lý do nghiệp vụ: email là định danh đăng nhập unique — đổi email tự do sẽ phá anchor KYC/audit và mở đường chiếm tài khoản. v1 không có self-service đổi email cũng như quên mật khẩu (CS + ADMIN reset — UC-01 AF-3). <span class="ref">BR-IDT-01</span> <span class="ref">FR-IDT-04</span> <span class="ref">docs/02 §5.1</span></span></li><li><span class="num">3</span><span><b>Avatar — contract còn hở (flag cho PM)</b>: `PATCH /users/me` nhận `avatarUrl`, nhưng `POST /media/upload` (endpoint 20) mới có kind `listing_photo|listing_doc|kyc_doc` — CHƯA có kind avatar. Wireframe vẽ cả 2 đường (nút upload + ô URL); khi BE chốt kind mới thì bỏ ô URL. Không tự mock API chưa có. <span class="ref">FR-IDT-04</span> <span class="ref">FR-HS-08</span></span></li><li><span class="num">4</span><span><b>Lưu thay đổi</b>: 4 trạng thái nút default / loading (disabled) / success (toast ok &quot;Đã lưu thay đổi hồ sơ&quot;) / error (field errors từ `VALIDATION_ERROR` — `errors[]` theo field, copy chuẩn docs/06 §5). &quot;Hủy bỏ thay đổi&quot; reset form về data server, hỏi xác nhận khi form dirty. <span class="ref">docs/05 §1.3</span></span></li><li><span class="num">5</span><span><b>Đổi mật khẩu</b> `POST /users/me/change-password` (7): mật khẩu cũ sai → 401, field error nguyên văn &quot;Email hoặc mật khẩu không đúng&quot;; thành công → thu hồi toàn bộ refresh token của các phiên KHÁC — toast phải nói rõ &quot;các thiết bị khác đã đăng xuất&quot; để user không hoảng. <span class="ref">FR-IDT-05</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">6</span><span><b>Strength meter là hint FE</b> (4 nấc: yếu/trung bình/mạnh/rất mạnh), không thay thế validation server — server mới là chốt theo BR-IDT-02 (hash argon2id). Mật khẩu mới trùng mật khẩu cũ → FE cảnh báo sớm, server 400. <span class="ref">BR-IDT-02</span></span></li><li><span class="num">7</span><span>Icon 🔒/👁/✎ trong wireframe là placeholder vị trí — production dùng icon set thật, không emoji. <span class="ref">docs/05 §7</span></span></li><li><span class="num">8</span><span><b>Cột trạng thái tài khoản chỉ đọc</b>, nguồn `GET /auth/me`: KYC status (NONE/PENDING/APPROVED/REJECTED), gói ACTIVE + endsAt, `auction_privilege` (GRANTED/SUSPENDED). SUSPENDED quyền đấu giá → badge danger + link giải thích BR-AU-16; tài khoản SUSPENDED (BR-IDT-07) → banner đầu trang &quot;Tài khoản bị tạm ngưng — liên hệ CSKH&quot;, form disabled. <span class="ref">docs/07 §2.1</span> <span class="ref">docs/08 §9</span></span></li></ol></div><h2 id="_2-đoi-mat-khau-—-cac-trang-thai-loi-bat-buoc-đoi-sau-admin-reset" tabindex="-1">2. Đổi mật khẩu — các trạng thái lỗi &amp; bắt buộc đổi sau ADMIN reset <a class="header-anchor" href="#_2-đoi-mat-khau-—-cac-trang-thai-loi-bat-buoc-đoi-sau-admin-reset" aria-label="Permalink to &quot;2. Đổi mật khẩu — các trạng thái lỗi &amp; bắt buộc đổi sau ADMIN reset&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-2"><div class="wf-col"><span class="wf-state-label">ERROR — MẬT KHẨU HIỆN TẠI SAI (401)</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Đổi mật khẩu</span><div class="wf-col" style="gap:2px;"><span class="wf-small wf-strong">Mật khẩu hiện tại *</span><div class="wf-input error"><span>••••••</span><span class="caret">👁</span></div><span class="wf-field-error">Email hoặc mật khẩu không đúng</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-strong">Mật khẩu mới *</span><div class="wf-input filled"><span>••••••••••••</span><span class="caret">👁</span></div></div><span class="wf-btn primary disabled">Đổi mật khẩu</span><span class="wf-small">Message nguyên văn bảng docs/06 §5 (`AUTH_INVALID_CREDENTIALS`) — không tiết lộ chi tiết hơn. Quên mật khẩu? v1 KHÔNG có self-reset: popover hướng dẫn gọi CSKH 1900-xxx (UC-01 AF-3), link đặt cạnh ô mật khẩu hiện tại. <span class="wf-callout danger">9</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — MẬT KHẨU MỚI YẾU / NHẬP LẠI LỆCH (400)</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Đổi mật khẩu</span><div class="wf-col" style="gap:2px;"><span class="wf-small wf-strong">Mật khẩu mới *</span><div class="wf-input error"><span>•••••</span><span class="caret">👁</span></div><div class="wf-row" style="gap:4px;margin-top:2px;"><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-danger);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span><span style="flex:1;height:6px;border-radius:3px;background:var(--wf-fill-dark);"></span></div><span class="wf-field-error">Chưa đạt: tối thiểu 8 ký tự, cần thêm 1 chữ HOA và 1 ký tự đặc biệt</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-strong">Nhập lại mật khẩu mới *</span><div class="wf-input error"><span>••••••••••••</span><span class="caret">👁</span></div><span class="wf-field-error">Mật khẩu nhập lại không khớp</span></div><span class="wf-btn primary disabled">Đổi mật khẩu</span><span class="wf-small">Checklist yêu cầu đổi màu theo từng tiêu chí đạt/chưa đạt (≥8 · HOA · số · đặc biệt). Nếu server trả 400 `VALIDATION_ERROR` thì map `errors[]` về đúng field — không parse `message`. <span class="ref">BR-IDT-02</span> <span class="ref">docs/06 §1</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">SUCCESS — TOAST + THU HỒI PHIÊN KHÁC</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast ok"><b>Đổi mật khẩu thành công</b> — các thiết bị khác đã đăng xuất, cần đăng nhập lại bằng mật khẩu mới</div><span class="wf-small">Form đổi mật khẩu reset + blur; khu &quot;Thông tin cá nhân&quot; không bị ảnh hưởng. <span class="ref">FR-IDT-05</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">BẮT BUỘC ĐỔI SAU ADMIN RESET (password_must_change)</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);margin:0;"><b>Tài khoản vừa được đặt lại mật khẩu — vui lòng đổi mật khẩu trước khi tiếp tục</b> <span class="wf-callout danger">10</span></div><span class="wf-small">Login bằng mật khẩu tạm OK, nhưng MỌI API khác trả 403 `AUTH_PASSWORD_MUST_CHANGE` cho tới khi đổi xong → FE điều hướng cứng vào form đổi mật khẩu (không escape sang màn khác). Đổi thành công → cờ `password_must_change` tắt → vào Dashboard SC-20. Mật khẩu tạm do ADMIN sinh 1 lần (BR-ADM-04, endpoint 63) — màn ADMIN reset vẽ ở SC-48, không ở đây.</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">9</span><span>Mọi message lỗi lấy <b>nguyên văn bảng docs/06 §5</b> — designer không viết lại copy. Link &quot;Quên mật khẩu?&quot; mở popover hướng dẫn liên hệ CS (v1 không self-reset — non-goal docs/01 §5.2). <span class="ref">docs/05 §3 SC-09</span> <span class="ref">UC-01 AF-3</span></span></li><li><span class="num">10</span><span>Banner dùng đúng message `AUTH_PASSWORD_MUST_CHANGE`. Đây là màn &quot;forced change&quot; — bố cục tối giản chỉ còn khối đổi mật khẩu, sidebar trạng thái ẩn. <span class="ref">docs/06 §4.8b</span> <span class="ref">docs/07 §2.1</span></span></li></ol></div><h2 id="_3-mobile-360px-—-form-mot-cot-sidebar-thanh-card-trang-thai-đau-trang" tabindex="-1">3. Mobile 360px — form một cột, sidebar thành card trạng thái đầu trang <a class="header-anchor" href="#_3-mobile-360px-—-form-mot-cot-sidebar-thanh-card-trang-thai-đau-trang" aria-label="Permalink to &quot;3. Mobile 360px — form một cột, sidebar thành card trạng thái đầu trang&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — HỒ SƠ</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">3</span></span></div><div class="wf-container" style="padding:12px;"><span class="wf-title lg">Hồ sơ cá nhân</span><div class="wf-row between middle" style="margin:8px 0;padding:8px 10px;border:1px solid var(--wf-line);border-radius:8px;background:var(--wf-fill);"><span class="wf-small">KYC <span class="wf-badge ok">APPROVED</span> · Gói <span class="wf-badge wf-vip">VIP_STANDARD</span></span></div><div class="wf-col" style="gap:8px;"><div class="wf-row middle" style="gap:10px;"><div class="wf-img" style="min-height:56px;width:56px;flex:none;border-radius:50%;"><span>AVA</span></div><span class="wf-btn sm">Đổi ảnh</span></div><div class="wf-col" style="gap:3px;"><span class="wf-small wf-strong">Họ tên *</span><div class="wf-input filled"><span>NGUYEN VAN A</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:3px;"><span class="wf-small wf-strong">Email — không thể đổi 🔒</span><div class="wf-input filled" style="background:var(--wf-fill);color:var(--wf-ink-soft);"><span>nguyenvana@example.com</span></div><span class="wf-small">Cần đổi? Gọi CSKH 1900-xxx</span></div><div class="wf-col" style="gap:3px;"><span class="wf-small wf-strong">Số điện thoại</span><div class="wf-input filled"><span>0912 345 678</span><span class="caret">✎</span></div></div><span class="wf-btn primary block">Lưu thay đổi</span><span class="wf-btn ghost block">Đổi mật khẩu</span></div></div></div></div><div class="wf-col" style="max-width:320px;justify-content:center;"><div class="wf-note"><b>Khác biệt mobile</b>: khối &quot;Đổi mật khẩu&quot; thu thành nút ghost mở section riêng (điều hướng trong trang hoặc bottom-sheet) — tránh 2 form dài chồng nhau. Card trạng thái tài khoản rút thành 1 dòng badge sticky dưới title.</div><div class="wf-note">&quot;Lưu thay đổi&quot; là nút block cuối form; khi form dirty mà user back → dialog xác nhận &quot;Chưa lưu thay đổi — rời trang?&quot; (pattern chung toàn site).</div><div class="wf-note">Bàn phím mobile: input mật khẩu `type=password` + nút hiện/ẩn; SĐT bật bàn phím số. Label luôn hiện (docs/05 §1.7 — không placeholder-thay-label).</div></div></div></div><h2 id="_4-loading-error-khung-trang-4-trang-thai-bat-buoc" tabindex="-1">4. Loading / Error khung trang (4 trạng thái bắt buộc) <a class="header-anchor" href="#_4-loading-error-khung-trang-4-trang-thai-bat-buoc" aria-label="Permalink to &quot;4. Loading / Error khung trang (4 trạng thái bắt buộc)&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-2"><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON FORM</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row middle" style="gap:10px;"><div class="wf-skeleton" style="width:56px;height:56px;border-radius:50%;"></div><div class="wf-grow wf-col" style="gap:6px;"><div class="wf-skeleton" style="height:14px;width:40%;"></div><div class="wf-skeleton" style="height:14px;width:70%;"></div></div></div><div class="wf-skeleton" style="height:38px;"></div><div class="wf-skeleton" style="height:38px;"></div><div class="wf-skeleton" style="height:38px;"></div><span class="wf-small">Nút &quot;Lưu&quot; disabled tới khi `GET /auth/me` về; sidebar trạng thái cũng skeleton 3 dòng.</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — KHÔNG LOAD ĐƯỢC HỒ SƠ</span><div class="wf-card"><div class="pad"><div class="wf-error-box"><div class="wf-title">Không tải được hồ sơ</div><div class="wf-text" style="margin-top:6px;">Thử lại; nếu tiếp diễn liên hệ CSKH 1900-xxx kèm mã trace.</div><div class="wf-trace" style="margin-top:8px;">traceId: 5c1e88ab…77f0</div><span class="wf-btn" style="margin-top:10px;">Thử lại</span></div><span class="wf-small">401 hết hạn giữa phiên → silent refresh tự động (UC-01 AF-2), không hiện lỗi; refresh reuse → logout về `/dang-nhap` kèm banner &quot;Phiên hết hạn, đăng nhập lại&quot;. <span class="ref">docs/05 §2</span></span></div></div></div></div></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-29" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-29 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-29" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-29&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (form + sidebar trạng thái sticky) / mobile 360 (một cột, đổi mật khẩu tách section) / tablet 768 (sidebar xuống dưới form)</li><li>[ ] Email input có affordance &quot;khóa&quot; rõ (icon + màu fill + hint CS) — không để user tưởng bug</li><li>[ ] Strength meter 4 nấc + checklist tiêu chí BR-IDT-02 đổi màu realtime; trạng thái nút disabled khi form chưa hợp lệ</li><li>[ ] Đủ trạng thái: default · loading skeleton · success toast (kèm copy &quot;thiết bị khác đã đăng xuất&quot;) · 401 mật khẩu sai · 400 mật khẩu yếu/nhập lệch · forced-change (password_must_change) · error khung trang + traceId</li><li>[ ] Popover &quot;Quên mật khẩu?&quot; → hướng dẫn gọi CSKH (không form reset — v1 non-goal)</li><li>[ ] Cờ avatar-upload contract hở (kind media chưa có &quot;avatar&quot;) — chờ PM/BE chốt, ghi chú trong frame</li><li>[ ] Không emoji icon trong UI production (🔒/👁/✎ là placeholder vị trí)</li><li>[ ] Copy lỗi nguyên văn docs/06 §5; giờ <code>dd/MM/yyyy HH:mm</code> + GMT+7; validate onBlur + onSubmit, message tại field</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',16)])])}const g=a(l,[["render",c]]);export{f as __pageData,g as default};
